async function seed() {
    try {
        console.log('Connecting to database...');
        await connectDB();

        console.log('Clearing old questions collection...');
        await Questions.deleteMany({});

        let totalQuestions = 0;
        const formattedSets = [];

        for (const set of setsData) {
            const questionsArray = [];

            for (let i = 0; i < set.raw.length; i++) {
                const [qText, dOpt, iOpt, sOpt, cOpt] = set.raw[i];

                const options = shuffle([
                    { text: dOpt, type: 'D' },
                    { text: iOpt, type: 'I' },
                    { text: sOpt, type: 'S' },
                    { text: cOpt, type: 'C' },
                ]);

                questionsArray.push({
                    qId: i + 1,
                    question: qText,
                    options: options,
                });
            }

            formattedSets.push({
                setId: set.setId,
                questions: questionsArray,
            });

            totalQuestions += questionsArray.length;
            console.log(`✓ Prepared Set ${set.setId}: "${set.title}" (${questionsArray.length} questions)`);
        }

        console.log(`\nInserting ${formattedSets.length} sets (${totalQuestions} total questions) into MongoDB...`);
        const inserted = await Questions.insertMany(formattedSets);

        console.log(`\n🎉 SUCCESS! Uploaded ${inserted.length} question sets with ${totalQuestions} questions total.`);
        
        // Quick verification
        const count = await Questions.countDocuments();
        console.log(`Verified MongoDB document count: ${count} sets`);

        process.exit(0);
    } catch (err) {
        console.error('❌ Seeding failed:', err);
        process.exit(1);
    }
}

seed();
